from typing import List

def parse_music(music_string: str) -> List[int]:
    beat_map = {'o': 4, 'o|': 2, '.|': 1}
    beats = []
    current_beat = 0

    for char in music_string:
        if char in beat_map:
            beats.append(current_beat)
            current_beat += beat_map[char]
        else:
            raise ValueError(f"Invalid character {char} found in music string.")

    return beats

