import string


def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])


# Optional: To handle both lowercase and uppercase characters.

def encode_shift_case_insensitive(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet, case-insensitive.
    """
    return "".join([chr(((ord(ch.lower()) + 5 - ord("a")) % 26) + ord("a")) if ch.islower()
                    else chr(((ord(ch.upper()) - 5 - ord("A")) % 26) + ord("A")) for ch in s])


# Optional: To make the decode function case-insensitive as well.

def decode_shift_case_insensitive(s: str):
    """
    takes as input string encoded with encode_shift_case_insensitive function. Returns decoded string, case-insensitive.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) if ch.islower()
                    else chr(((ord(ch) - 5 - ord("A")) % 26) + ord("A")) for ch in s])

