def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True


def is_multiply_prime(a):
    """
    Returns True if the given number is the multiplication of 3 prime numbers,
    and False otherwise. The function also ensures the input number is within
    the specified range (less than 100).
    """
    if a < 1 or a > 99:
        return False

    prime_factors = set()
    for i in range(2, a):
        if a % i == 0:
            if is_prime(i):
                prime_factors.add(i)
                if len(prime_factors) > 3:
                    return False
                a //= i

    return len(prime_factors) == 3

