                continue
            if i == 0:
                dp[i][j] = grid[i][j] + dp[i][j-1]
            elif j == 0:
                dp[i][j] = grid[i][j] + dp[i-1][j]
            else:
                dp[i][j] = grid[i][j] + min(dp[i-1][j], dp[i][j-1])

    minPath = []

    def dfs(x, y, visited, path):
        if len(path) == k:
            return path
        if (x, y) in visited:
            return None
        visited.add((x, y))
        minPath.append(grid[x][y])

        min_dist = float('inf')
        next_cell = None
        for dx, dy in ((0, 1), (1, 0)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                next_path = path + [grid[nx][ny]]
                next_dist = dp[nx][ny] - dp[x][y]
                if next_dist < min_dist:
                    next_cell = (nx, ny)
                    min_dist = next_dist

        if next_cell:
            next_path = dfs(next_cell[0], next_cell[1], set(visited), next_path)
            if not next_path:
                return None
        return next_path

    minPath = dfs(0, 0, set(), [])
    return minPath

